255	    @Override
256	    @Transactional
257	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
258	        rejectWhenDailyLimitReached(owner);
259	        rejectWhenCityAtCapacity(owner);
260	        owner.setHouseholdId(deriveHouseholdId(owner));
261	        List<Owner> householdMembers = findHouseholdMembers(owner);
262	        rejectWhenHouseholdDuplicate(owner, householdMembers, sharesHousehold);
263	        assignPossibleDuplicate(owner);
264	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
265	        if (owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(deriveCustomerCode(owner));
267	        }
268	        if (owner.getNamesakeCount() == null) {
269	            owner.setNamesakeCount(countNamesakes(owner));
270	        }
271	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
272	        ownerRepository.save(owner);
273	    }
274	
275	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
276	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
277	
278	    /**
279	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
280	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
281	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
282	     * today by the controller, determines which day is counted — the same accumulation path as the
283	     * daily-limit rule.
284	     */
285	    private boolean exceedsBulkSignupThreshold(Owner owner) {
286	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
287	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
288	    }
289	
290	    /**
291	     * Count the existing owners that already share this owner's first name and last name,
292	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
293	     * before the owner is persisted, so it reflects the owners present at creation time.
294	     */
295	    private int countNamesakes(Owner owner) {
296	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
297	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
298	        return (int) ownerRepository.findAll().stream()
299	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
300	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
301	            .count();
302	    }
303	
304	    /**
305	     * The existing owners that already belong to this owner's household, i.e. those carrying the
306	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
307	     * household id is derived purely from the normalized last name and postcode, this is exactly
308	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
309	     * persisted, so it reflects the owners present at creation time. The owner's own
310	     * {@code householdId} must already be assigned before calling.
311	     */
312	    private List<Owner> findHouseholdMembers(Owner owner) {
313	        String householdId = owner.getHouseholdId();
314	        return ownerRepository.findAll().stream()
315	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
316	            .toList();
317	    }
318	
319	    /**
320	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
321	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
322	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
323	     * map to the same value automatically, without any opt-in, so they form one household.
324	     */
325	    private static String deriveHouseholdId(Owner owner) {
326	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
327	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
328	        return sha256HexPrefix(lastName + "|" + postcode, 12);
329	    }
330	
331	    /**
332	     * Reject the create when another owner already belongs to this owner's household (same
333	     * deterministic {@code householdId}, i.e. the same last name and postcode) as a
334	     * {@code 409 Conflict}. The single exception to the block is {@code sharesHousehold}: when set
335	     * the new owner is accepted as a declared member of the existing household rather than rejected.
336	     * Evaluated after the household id has been assigned and before the owner is persisted, so it
337	     * reflects the owners present at creation time.
338	     */
339	    private void rejectWhenHouseholdDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
340	        if (!householdMembers.isEmpty() && !sharesHousehold) {
341	            throw new DuplicateIdentityException(
342	                "an owner already exists in household " + owner.getHouseholdId());
343	        }
344	    }
345	
346	    /**
347	     * Set the new owner's soft-duplicate flags. A declared member of an existing household (reached
348	     * only via {@code sharesHousehold}) is explicitly not a suspected duplicate, and an owner that
349	     * is the first in its household has nothing to be a duplicate of; any other case would already
350	     * have been rejected as a household duplicate. The flags are therefore always cleared here, but
351	     * set explicitly so the field is always present in the response. Evaluated after the
352	     * household-duplicate check and before the owner is persisted.
353	     */
354	    private void assignPossibleDuplicate(Owner owner) {
355	        owner.setPossibleDuplicate(false);
356	        owner.setPossibleDuplicateOf(null);
357	    }
358	
359	    /** Maximum number of owners that may be created on any single day (by registration date). */
360	    private static final long DAILY_OWNER_LIMIT = 100L;
361	
362	    /**
363	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
364	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
365	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
366	     * to today by the controller, determines which day the limit is checked against.
367	     */
368	    private void rejectWhenDailyLimitReached(Owner owner) {
369	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
370	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
371	            throw new DailyOwnerLimitExceededException(
372	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
373	        }
374	    }
375	
376	    /**
377	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
378	     * before the owner is persisted, so it reflects the owners present at creation time.
379	     */
380	    private long countOwnersRegisteredOn(LocalDate day) {
381	        return ownerRepository.findAll().stream()
382	            .filter(existing -> day.equals(existing.getRegistrationDate()))
383	            .count();
384	    }
385	
386	    /** Maximum number of owners allowed to live in any single city. */
387	    private static final long CITY_CAPACITY = 50L;
388	
389	    /**
390	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
391	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
392	     * is persisted, so it reflects the owners present at creation time.
393	     */
394	    private void rejectWhenCityAtCapacity(Owner owner) {
395	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
396	            throw new CityCapacityExceededException(
397	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
398	        }
399	    }
400	
401	    /**
402	     * Count the existing owners that already live in this owner's city, compared
403	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
404	     * owner is persisted, so it reflects the owners present at creation time.
405	     */
406	    private long countOwnersInCity(Owner owner) {
407	        String city = IdentityNormalizer.normalize(owner.getCity());
408	        return ownerRepository.findAll().stream()
409	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
410	            .count();
411	    }
412	
413	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
414	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
415	        "NSW", new int[] {2000, 2099},
416	        "VIC", new int[] {3000, 3099},
417	        "QLD", new int[] {4000, 4099});
418	
419	    /** Region code used when the postcode maps to no known region (or is absent). */
420	    private static final String UNKNOWN_REGION = "UNKNOWN";
421	
422	    /**
423	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
424	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
425	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
426	     * name. No sequence number is used; the identity is fully derived from the region and hash.
427	     */
428	    private String deriveCustomerCode(Owner owner) {
429	        String region = regionForPostcode(owner.getPostcode());
430	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
431	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
432	        return region + "-" + sha256Hex8(telephone + lastName);
433	    }
434	
435	    /**
436	     * Returns the region code whose inclusive postcode range contains {@code postcode}
437	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
438	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
439	     */
440	    private static String regionForPostcode(String postcode) {
441	        if (postcode == null || !postcode.matches("\\d{4}")) {
442	            return UNKNOWN_REGION;
443	        }
444	        int value = Integer.parseInt(postcode);
445	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
446	            int[] range = entry.getValue();
447	            if (value >= range[0] && value <= range[1]) {
448	                return entry.getKey();
449	            }
450	        }
451	        return UNKNOWN_REGION;
452	    }
453	
454	    /**
455	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
456	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
457	     */
458	    private static String sha256Hex8(String value) {
459	        try {
460	            byte[] digest = MessageDigest.getInstance("SHA-256")
461	                .digest(value.getBytes(StandardCharsets.UTF_8));
462	            StringBuilder sb = new StringBuilder(8);
463	            for (int i = 0; i < 4; i++) {
464	                sb.append(String.format("%02X", digest[i]));
465	            }
466	            return sb.toString();
467	        }
468	        catch (NoSuchAlgorithmException e) {
469	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
470	        }
471	    }
472	
473	    /**
474	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
475	     * the UTF-8 bytes of {@code value}.
476	     */
477	    private static String sha256HexPrefix(String value, int hexChars) {
478	        try {
479	            byte[] digest = MessageDigest.getInstance("SHA-256")
480	                .digest(value.getBytes(StandardCharsets.UTF_8));
481	            StringBuilder sb = new StringBuilder(hexChars);
482	            for (int i = 0; sb.length() < hexChars; i++) {
483	                sb.append(String.format("%02x", digest[i]));
484	            }
485	            return sb.substring(0, hexChars);
486	        }
487	        catch (NoSuchAlgorithmException e) {
488	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
489	        }
490	    }
491	
492	    @Override
493	    @Transactional(readOnly = true)
494	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
495	        return ownerRepository.findByLastName(lastName);
496	    }
