504	    @Override
505	    @Transactional(readOnly = true)
506	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
507	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
508	    }
509	
510	    private <T> T findEntityById(Supplier<T> supplier) {
511	        try {
512	            return supplier.get();
513	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
514	            // Just ignore not found exceptions for Jdbc/Jpa realization
515	            return null;
516	        }
517	    }
518	
